@reference "../../app/globals.css";

@property --rotation {
  syntax: '<angle>';
  inherits: true;
  initial-value: 0;
}

.circular-gallery-wrapper {
  --card-trans-duration: 1000ms;
  --card-trans-easing: linear(
    0,
    0.01 0.8%,
    0.038 1.6%,
    0.154 3.4%,
    0.781 9.7%,
    1.01 12.5%,
    1.089 13.8%,
    1.153 15.2%,
    1.195 16.6%,
    1.219 18%,
    1.224 19.7%,
    1.208 21.6%,
    1.172 23.6%,
    1.057 28.6%,
    1.007 31.2%,
    0.969 34.1%,
    0.951 37.1%,
    0.953 40.9%,
    0.998 50.4%,
    1.011 56%,
    0.998 74.7%,
    1
  );
  --card-width: clamp(40px, 7vw, 120px);
  --card-border-radius: 1vw;
  --radius: 40vmin;
  --arc-size: 0.95; /* essentially the distance between cards */
  --arc-center: 0.275; /* start at bottom to last card will be at the top */
  --arc-start: calc(var(--arc-center) - var(--arc-size) / 2);
  --arc-shift-delta: 0.0075;
  --clr-lines: rgba(255 255 255 / 0.25);

  anchor-name: --center;
  position: absolute;
  inset: 0;
  margin: auto;
  width: var(--radius);
  height: var(--radius);
  aspect-ratio: 1;
  transform: rotate(var(--rotation));
  transition: transform 700ms linear;
  display: grid;
  place-content: center;
}

.circular-gallery-wrapper h1 {
  margin: 0;
  text-align: center;
  font-size: clamp(1.2rem, 3.5vw + 0.045rem, 3rem);
  color: white;
}

.circular-gallery-wrapper > div {
  --card-i: var(--i);
  /* var(--cards) is injected dynamically by React */
  --arc-step: calc(var(--arc-size) / (var(--cards) - 1));
  --arc-shift: calc(var(--arc-shift-delta) * var(--d, 1));
  --card-offset-distance: calc(
    (
        var(--arc-start) + (var(--card-i) - 1) * var(--arc-step) +
          var(--arc-shift)
      ) *
      100%
  );

  &:has(a:hover),
  &:target {
    --title-opacity: 1;
  }

  &:target {
    --zindex: 2;
    --center-opacity: 1;
    --center-scale: 1;
    --image-outline-color: var(--clr-lines);
  }

  &::before,
  &::after {
    content: '';
    position: absolute;
    position-anchor: --center;
    transform: rotate(calc(var(--rotation) * -1));
    transition-timing-function: ease-in-out;
  }

  /* large image in center of wrapper */
  &::before {
    position-area: span-all;
    width: calc(var(--radius));
    aspect-ratio: 1;
    border-radius: 9in;
    background: var(--bg-img);
    box-sizing: border-box;
    outline: 10px solid var(--clr-lines);
    outline-offset: -10px;
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    opacity: var(--center-opacity, 0);
    scale: var(--center-scale, 0);
    pointer-events: none;
    transition-property: scale, opacity;
    transition-duration: 300ms, 150ms;
    z-index: 0;
  }

  /* image title - over thumb */
  &::after {
    content: attr(data-title);
    position-anchor: --card;
    position-area: center span-all;
    z-index: 2;
    pointer-events: none;
    opacity: var(--title-opacity, 0);
    transition-property: opacity, transform;
    transition-duration: 150ms;
    border: 1px solid rgb(255 255 255 / 0.75);
    background: rgb(0 0 0 / 0.25);
    color: white;
    backdrop-filter: blur(3px);
    padding: 0.25em 1em;
    border-radius: 5px;
    font-size: clamp(0.6rem, 1vw + 0.045rem, 0.85rem);
    @starting-style {
      opacity: 0;
    }
  }

  /* links with images are placed in a circle */
  a {
    position: absolute;
    display: block;
    width: var(--card-width);
    aspect-ratio: 4/6;
    border-radius: var(--card-border-radius);
    border: 2px solid transparent;
    offset-path: circle(var(--radius) at 50% 50%);
    offset-distance: var(--card-offset-distance);
    offset-rotate: auto;
    offset-anchor: 50% 0%;
    transition: offset var(--card-trans-duration) var(--card-trans-easing);
    z-index: var(--zindex, 1);
    anchor-name: --card;
  }

  a img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    border-radius: inherit;
    outline: 5px solid var(--image-outline-color, transparent);
    outline-offset: -5px;
    transition: outline 300ms ease-in-out;
  }
}

/* ============================================================
   FORWARD siblings (clockwise / +)
   ============================================================ */
/* +1 */
.circular-gallery-wrapper:has(> *:hover) > *:hover + *,
.circular-gallery-wrapper:has(> :last-child:hover) > :nth-child(1) {
  --d: 3;
}

/* +2 */
.circular-gallery-wrapper:has(> *:hover) > *:hover + * + *,
.circular-gallery-wrapper:has(> :last-child:hover) > :nth-child(2),
.circular-gallery-wrapper:has(> :nth-last-child(2):hover) > :nth-child(1) {
  --d: 2;
}

/* +3 */
.circular-gallery-wrapper:has(> *:hover) > *:hover + * + * + *,
.circular-gallery-wrapper:has(> :last-child:hover) > :nth-child(3),
.circular-gallery-wrapper:has(> :nth-last-child(2):hover) > :nth-child(2),
.circular-gallery-wrapper:has(> :nth-last-child(3):hover) > :nth-child(1) {
  --d: 1;
}

/* +4 */
.circular-gallery-wrapper:has(> *:hover) > *:hover + * + * + * + *,
.circular-gallery-wrapper:has(> :last-child:hover) > :nth-child(4),
.circular-gallery-wrapper:has(> :nth-last-child(2):hover) > :nth-child(3),
.circular-gallery-wrapper:has(> :nth-last-child(3):hover) > :nth-child(2),
.circular-gallery-wrapper:has(> :nth-last-child(4):hover) > :nth-child(1) {
  --d: 0.5;
}

/* ============================================================
   BACKWARD siblings (counter-clockwise / −)
   ============================================================ */
/* −1 */
.circular-gallery-wrapper *:has(+ *:hover),
.circular-gallery-wrapper:has(> :nth-child(1):hover) :nth-last-child(1) {
  --d: -3;
}

/* −2 */
.circular-gallery-wrapper *:has(+ * + *:hover),
.circular-gallery-wrapper:has(> :nth-child(1):hover) :nth-last-child(2),
.circular-gallery-wrapper:has(> :nth-child(2):hover) :nth-last-child(1) {
  --d: -2;
}

/* −3 */
.circular-gallery-wrapper *:has(+ * + * + *:hover),
.circular-gallery-wrapper:has(> :nth-child(1):hover) :nth-last-child(3),
.circular-gallery-wrapper:has(> :nth-child(2):hover) :nth-last-child(2),
.circular-gallery-wrapper:has(> :nth-child(3):hover) :nth-last-child(1) {
  --d: -1;
}

/* −4 */
.circular-gallery-wrapper *:has(+ * + * + * + *:hover),
.circular-gallery-wrapper:has(> :nth-child(1):hover) :nth-last-child(4),
.circular-gallery-wrapper:has(> :nth-child(2):hover) :nth-last-child(3),
.circular-gallery-wrapper:has(> :nth-child(3):hover) :nth-last-child(2),
.circular-gallery-wrapper:has(> :nth-child(4):hover) :nth-last-child(1) {
  --d: -0.5;
}
